	CONSTRAINT "zed_project_invitations_role_chk" CHECK ((role)::text = ANY ((ARRAY['admin'::character varying, 'member'::character varying, 'reader'::character varying])::text[])),
	CONSTRAINT "zed_project_invitations_token_hash_chk" CHECK ((token_hash)::text ~ '^[a-f0-9]{64}$'::text)
);

CREATE TABLE "zed_project_members" (
	"project_id" uuid NOT NULL,
	"user_id" uuid NOT NULL,
	"role" varchar(16) NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "zed_project_members_pkey" PRIMARY KEY("project_id","user_id"),
	CONSTRAINT "zed_project_members_role_chk" CHECK ((role)::text = ANY ((ARRAY['owner'::character varying, 'admin'::character varying, 'member'::character varying, 'reader'::character varying])::text[]))
);

CREATE TABLE "zed_projects" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"org_id" uuid NOT NULL,
	"slug" varchar(64) NOT NULL,
	"name" text NOT NULL,
	"description" text,
	"visibility" varchar(16) DEFAULT 'private' NOT NULL,
	"settings" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"created_by_user_id" uuid,
	"is_soft_deleted" boolean DEFAULT false NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "zed_projects_description_size_chk" CHECK ((description IS NULL) OR (octet_length(description) <= 4096)),
	CONSTRAINT "zed_projects_name_size_chk" CHECK ((octet_length(name) >= 1) AND (octet_length(name) <= 200)),
	CONSTRAINT "zed_projects_settings_object_chk" CHECK (jsonb_typeof(settings) = 'object'::text),
	CONSTRAINT "zed_projects_slug_format_chk" CHECK ((slug)::text ~ '^[a-z0-9][a-z0-9._-]{0,62}[a-z0-9]$'::text),
	CONSTRAINT "zed_projects_visibility_chk" CHECK ((visibility)::text = ANY ((ARRAY['private'::character varying, 'internal'::character varying, 'public'::character varying])::text[]))
);

CREATE TABLE "zed_users" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"shared_auth_subject" uuid NOT NULL,
	"auth_realm" varchar(16) DEFAULT 'customer' NOT NULL,
	"email" text,
	"display_name" text,
	"avatar_url" text,
	"settings" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"is_soft_deleted" boolean DEFAULT false NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "zed_users_auth_realm_chk" CHECK ((auth_realm)::text = ANY ((ARRAY['customer'::character varying, 'admin'::character varying])::text[])),
	CONSTRAINT "zed_users_avatar_url_size_chk" CHECK ((avatar_url IS NULL) OR (octet_length(avatar_url) <= 2048)),
	CONSTRAINT "zed_users_display_name_size_chk" CHECK ((display_name IS NULL) OR (octet_length(display_name) <= 200)),
	CONSTRAINT "zed_users_email_size_chk" CHECK ((email IS NULL) OR ((octet_length(email) >= 3) AND (octet_length(email) <= 320))),
	CONSTRAINT "zed_users_settings_object_chk" CHECK (jsonb_typeof(settings) = 'object'::text)
);

